753:         ///     Invokes routine registered during MAJORBBS->RTKICK()
754:         ///
755:         ///     Methods registered using RTKICK are automatically invoked after a specified delay (in seconds). Methods
756:         ///     only execute once and are then discarded.
757:         /// </summary>
758:         [MethodImpl(MethodImplOptions.AggressiveInlining)]
759:         private void ProcessRTKICK()
760:         {
761:             //Check for any rtkick routines
762:             foreach (var module in _modules.Values.Where(m => (bool)m.ModuleConfig.ModuleEnabled))
763:             {
764:                 if (module.RtkickRoutines.Count == 0) continue;
765: 
766:                 foreach (var (key, value) in module.RtkickRoutines.ToList())
767:                 {
768:                     if (!value.Executed && value.Elapsed.ElapsedMilliseconds > value.Delay * 1000)
769:                     {
770: #if DEBUG
771:                         Logger.Info($"Running RTKICK-{key}: {value}");
772: #endif
773:                         Run(module.ModuleIdentifier, value, ushort.MaxValue);
774: 
775:                         value.Elapsed.Stop();
776:                         value.Executed = true;
777:                         module.RtkickRoutines.Remove(key);
778:                     }
779:                 }

790:         ///     Unlike RTKICK, methods registered with RTIHDLR() only need to be registered once and will run until the BBS
791:         ///     is shut down.
792:         /// </summary>
793:         [MethodImpl(MethodImplOptions.AggressiveInlining)]
794:         private void ProcessRTIHDLR()
795:         {
796:             //Too soon? Bail.
797:             if (_realTimeStopwatch.ElapsedMilliseconds <= 55) return;
798: 
799:             foreach (var m in _modules.Values.Where(m => (bool)m.ModuleConfig.ModuleEnabled))
800:             {
801:                 if (m.RtihdlrRoutines.Count == 0) continue;
802: 
803:                 foreach (var r in m.RtihdlrRoutines)
804:                 {
805:                     Run(m.ModuleIdentifier, r.Value, ushort.MaxValue);
806:                 }
807:             }
808: 
809:             _realTimeStopwatch.Restart();
810:         }
